mapper.select:
SELECT id, user_id, activity_id, request_id, status, created_at
FROM registration
WHERE user_id = #{userId}
  AND request_id = #{requestId}

SELECT id, user_id, activity_id, request_id, status, created_at
FROM registration
WHERE user_id = #{userId}
  AND activity_id = #{activityId}

SELECT id, user_id, activity_id, request_id, status, created_at
FROM registration
WHERE id = #{id}
  AND user_id = #{userId}

SELECT id, user_id, activity_id, request_id, status, created_at
FROM registration
WHERE user_id = #{userId}
ORDER BY created_at DESC, id DESC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*)
FROM registration
WHERE user_id = #{userId}
